import 'package:flutter/material.dart';
import '../api.dart';
class ProviderAgendaScreen extends StatefulWidget { const ProviderAgendaScreen({super.key}); @override State<ProviderAgendaScreen> createState() => _ProviderAgendaScreenState(); }
class _ProviderAgendaScreenState extends State<ProviderAgendaScreen> { final api = JopetsApi(); List<Map<String, dynamic>> rows = []; String? error; bool loading = true; @override void initState() { super.initState(); load(); } Future<void> load() async { setState(() { loading = true; error = null; }); try { final value = await api.providerAgenda(); if (mounted) setState(() => rows = value); } catch (e) { if (mounted) setState(() => error = e.toString()); } finally { if (mounted) setState(() => loading = false); } } @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Agenda'), actions: [IconButton(onPressed: load, icon: const Icon(Icons.refresh))]), body: loading ? const Center(child: CircularProgressIndicator()) : error != null ? Center(child: Text(error!)) : rows.isEmpty ? const Center(child: Text('El servidor no devolvió citas asignadas.')) : ListView.builder(itemCount: rows.length, itemBuilder: (_, i) { final row = rows[i]; return ListTile(leading: const Icon(Icons.event), title: Text(row['id']?.toString() ?? ''), subtitle: Text('Mascota ${row['pet_id'] ?? ''} • ${row['state'] ?? ''}')); })); }
